#include "gpu_health_reduce.cuh"
#include "gpu_adam_device.cuh"
#include <cstdio>
int main(){using namespace tao::dual;try{Vec w(1003,.2f),g(1003),zero(1003);double norm2=0;for(size_t i=0;i<g.size();++i){g[i]=float(int(i%29)-14);double z=double(g[i])/7;norm2+=z*z;}Device a(w),b(w),grad(g),ma(zero),mb(zero),va(zero),vb(zero);GpuHealth h;h.add(grad,false,7);float factor=float(1./7/std::max(1.,std::sqrt(norm2)));ds_adamw<<<8,128>>>(a.p,grad.p,ma.p,va.p,1003,factor,.0005f,.01f,.1f,.001f);ds_adamw_device<<<8,128>>>(b.p,grad.p,mb.p,vb.p,1003,h.sum,h.bad,7,.0005f,.01f,.1f,.001f);check(cudaGetLastError());h.finish();float error=0;auto compare=[&](Device&x,Device&y){auto xx=x.host(),yy=y.host();for(size_t i=0;i<xx.size();++i){if(!std::isfinite(yy[i]))throw std::runtime_error("nonfinite output");error=std::max(error,std::abs(xx[i]-yy[i]));}};compare(a,b);compare(ma,mb);compare(va,vb);if(error>1e-7)return 1;auto before=b.host();g[2]=std::numeric_limits<float>::infinity();check(cudaMemcpy(grad.p,g.data(),g.size()*4,cudaMemcpyHostToDevice));h.reset();h.add(grad,false,7);ds_adamw_device<<<8,128>>>(b.p,grad.p,mb.p,vb.p,1003,h.sum,h.bad,7,.0005f,.01f,.1f,.001f);bool rejected=false;try{h.finish();}catch(...){rejected=true;}if(!rejected||b.host()!=before)return 2;printf("PASS GPU Adam clipped weights/moments/variance maxerror=%.9g invalidgradient skipsweights\n",error);return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 3;}}
